SELECT ROUND(AVG(freight)::numeric, 2) AS avg_freight_cost
FROM orders
WHERE ship_country = 'UK';

SELECT COUNT(*) AS customers_with_no_orders
FROM customers c
WHERE NOT EXISTS (
    SELECT 1 FROM orders o WHERE o.customer_id = c.customer_id
);

SELECT COUNT(*) AS late_shipments
FROM orders
WHERE shipped_date > required_date;

SELECT ROUND(AVG(line_item_count), 2) AS avg_line_items_per_order
FROM (
    SELECT order_id, COUNT(*) AS line_item_count
    FROM order_details
    GROUP BY order_id
) AS order_counts;
